G=json.loads((ROOT/'data/unej_geography.json').read_text());ss=np.array(G['s']);lat=np.array(G['lat']);lon=np.array(G['lng']);east=(lon-lon[0])*111195*np.cos(np.deg2rad(lat[0]));north=(lat-lat[0])*111195
